function setFooter(ws,m,txt){
  const ad='A'+(m.tot+1),c=ws.getCell(ad);
  if(!c.isMerged){
    const e=m.tot+(txt.split('\n').length>2?3:2);
    ws.mergeCells(ad+':H'+e);
    ws.getCell(ad).alignment={wrapText:true,vertical:'top',horizontal:'left'};
    ws.getCell(ad).font={size:8};
  }
  ws.getCell(ad).value=txt?txt:null;
}

function newrestCols(ws){
  const cp=s=>JSON.parse(JSON.stringify(s||{}));
  for(let r=12;r<=53;r++){['H','I'].forEach(c=>{const d=ws.getCell(c+r);d.style=cp(ws.getCell('G'+r).style)})}
  ws.getCell('H12').value='P.U';ws.getCell('I12').value='TOTAL';
  ws.getColumn('I').width=ws.getColumn('H').width||14.7;
  ws.unMergeCells('G53:H53');ws.mergeCells('G53:I53');
  try{ws.unMergeCells('A54:H58');ws.mergeCells('A54:I58')}catch(e){}
}
function expandRows(ws,m,extra){
  const last=m.r[1],tot=m.tot,maxR=Math.min(ws.rowCount,tot+8),nc=Math.max(ws.columnCount,10);
  const rng=s=>{const [a,b]=s.split(':');const p=x=>{const q=/([A-Z]+)(\d+)/.exec(x);return {c:q[1],r:+q[2]}};return {a:p(a),b:p(b||a)}};
  const merges=ws.model.merges.slice();
  const itemM=merges.map(rng).filter(x=>x.a.r===last&&x.b.r===last);
  const footM=merges.filter(s=>rng(s).a.r>=tot);
  footM.forEach(s=>ws.unMergeCells(s));
  const cp=s=>JSON.parse(JSON.stringify(s||{}));
  for(let r=maxR;r>=tot;r--){
    const src=ws.getRow(r),dst=ws.getRow(r+extra);dst.height=src.height;
    for(let c=1;c<=nc;c++){const s=src.getCell(c),d=dst.getCell(c);d.value=s.value;d.style=cp(s.style)}
  }
  for(let r=tot;r<tot+extra;r++){
    const dst=ws.getRow(r),s0=ws.getRow(last);dst.height=s0.height;
    for(let c=1;c<=nc;c++){const d=dst.getCell(c);d.value=null;d.style=cp(s0.getCell(c).style)}
  }
  footM.filter(s=>rng(s).a.r<=maxR).forEach(s=>{const x=rng(s);ws.mergeCells(x.a.c+(x.a.r+extra)+':'+x.b.c+(x.b.r+extra))});
  itemM.forEach(x=>{for(let r=tot;r<tot+extra;r++)ws.mergeCells(x.a.c+r+':'+x.b.c+r)});
}
$('bmod').onclick=async()=>{
  try{
    const k=$('mod').value,m={...MD[k],r:MD[k].r.slice()},cap=m.r[1]-m.r[0]+1;
    const wb=new ExcelJS.Workbook();
    await wb.xlsx.load(Uint8Array.from(atob(T[k]),c=>c.charCodeAt(0)).buffer);
    const ws=wb.worksheets[0];
    if(k==='NEWREST')newrestCols(ws);
    const ci=+$('cd').value,cq=+$('cq').value,cp=+$('cp').value,ct=+$('ct').value;
    const rows=rowsOut();
    if(rows.length>cap){const ex=rows.length-cap;expandRows(ws,m,ex);m.r=[m.r[0],m.r[1]+ex];m.tot+=ex}
    for(let r=m.r[0];r<=m.r[1];r++){['A',m.q,m.p,m.t].forEach(c=>{if(c)ws.getCell(c+r).value=null})}
    const tz=$('tzero').checked;let sq=0,st=0;const F2='#,##0.00';
    rows.forEach((r,i)=>{
      const n=m.r[0]+i,q=num(r[cq]);sq+=q;
      ws.getCell('A'+n).value=r[ci];ws.getCell(m.q+n).value=q;
      if(m.p&&cp>=0){
        const pu=num(r[cp]),t=ct>=0?num(r[ct]):Math.round(q*pu*100)/100;st+=t;
        ws.getCell(m.p+n).value=pu;ws.getCell(m.p+n).numFmt=F2;ws.getCell(m.t+n).value=t;ws.getCell(m.t+n).numFmt=F2;
      }
    });
    if(tz&&m.t)rows.forEach((r,i)=>{const c=ws.getCell(m.t+(m.r[0]+i));c.value=0;c.numFmt='0'});
    const ttc=$('mttc').value.trim(),tc=ws.getCell(m.q+m.tot);
    tc.value=ttc!==''?num(ttc):(m.p&&cp>=0?Math.round(st*100)/100:sq);
    if(ttc!==''||(m.p&&cp>=0))tc.numFmt=F2;
    const dv=$('mdate').value?$('mdate').value.split('-').reverse().join(' / '):'';
    ws.getCell(m.d).value=(m.dl||'')+dv;
    ws.getCell(m.s).value='SITE : '+$('msite').value;
    ws.getCell(m.m).value=$('mmat').value;
    setFooter(ws,m,$('mft').value.trim());
    const buf=await wb.xlsx.writeBuffer();
    save(k+' - '+($('msite').value||fname).replace(/[\\/:*?"<>|]/g,'')+'.xlsx',new Uint8Array(buf));
  }catch(e){toast('Erreur modèle : '+(e.message||e))}
};

